  // 期望值（和生成时同一套算法）
  D.val = function (moveKey, stat) {
    var m = D.mv[moveKey];
    if (!m) return 0;
    return m[0] * m[1] / 100 * 1.5 * stat;
  };

  D.of = function (id, type) {
    var list = D.rank[type];
    if (!list) return null;
    for (var i = 0; i < list.length; i++) {
      if (list[i][0] === id) {
        var m = D.mv[list[i][1]];
        return {
          type: type, rank: i + 1, total: list.length,
          key: list[i][1], pw: m[0], acc: m[1], cat: m[2] ? 'phys' : 'spec',
          name: m[3], stat: list[i][2], val: D.val(list[i][1], list[i][2])
        };
      }
    }
    return null;
  };

  D.mon = function (id) {
    var out = [];
    for (var i = 0; i < D.order.length; i++) {
      var r = D.of(id, D.order[i]);
      if (r) out.push(r);
    }
    out.sort(function (a, b) { return a.rank - b.rank; });
    return out;
  };

  D.top = function (type, n) {
    var list = D.rank[type] || [];
    var out = [];
    for (var i = 0; i < Math.min(n || 10, list.length); i++) {
      var m = D.mv[list[i][1]];
      out.push({
        rank: i + 1, id: list[i][0], name: D.nm[list[i][0]] || ('#' + list[i][0]),
        key: list[i][1], mv: m[3], pw: m[0], acc: m[1], cat: m[2] ? 'phys' : 'spec',
        stat: list[i][2], val: D.val(list[i][1], list[i][2])
      });
    }
    return out;
  };

