/* ===========================================================================
 * 第一百一十三批：把游戏新增的「全属性阿尔宙斯」放进本系威力表
 *
 * 依据（线上 app.0e84ded8d8.js）：
 *   - 形态 = [["fire","Feu"],["water","Eau"],["grass","Plante"],["electric","Électrik"],
 *             ["ice","Glace"],["fighting","Combat"],["poison","Poison"],["ground","Sol"],
 *             ["flying","Vol"],["psychic","Psy"],["bug","Insecte"],["rock","Roche"],
 *             ["ghost","Spectre"],["dragon","Dragon"],["dark","Ténèbres"],["steel","Acier"]]
 *            .map(([P,u],ve)=>({id:49301+ve,base:493,slug:`arceus-${P}`,
 *                               form:u,types:[P],single:!0,plate:P}))
 *     共 16 个石板形态；加原本的普通形态 493，游戏成就写「拥有阿尔宙斯的全部17种形态」。
 *     游戏没有 fairy 石板，所以这里也不造妖精阿尔宙斯（fairy 页保持原样）。
 *   - 每个形态把 learn 里的 judgment 换成 `judgment-<plate>`：
 *       t.MOVES[it] = {...MOVES.judgment, type:P.plate}
 *       MOVES.judgment = {power:100, acc:100, cat:"spec"}，中文名「制裁光砾」。
 *   - 形态种族值与 493 完全一致（六项 120），Lv100 特攻 = 2×120+5 = 245。
 *
 * 本表口径（与生成脚本一致）：mv[key] = [有效威力, 命中%, 1物/0特, 中文名]，
 * 命中率按 ACC_CURVE [40,150,80] 由威力换算，power100 → 100-(100-40)×20/110 = 89.09。
 * 期望值 = 100 × 0.8909 × 1.5 × 245 = 32740.575，和表内其它招式同一把尺子。
 *
 * 上面那行是自动生成的大 JSON，不手改；这里在加载后追加：名次由 D.val() 现算，
 * 按期望值从高到低插进各属性 rank，以后数据重生成也不会插错位置。
 * =========================================================================== */
(function (root) {
  'use strict';
  var D = root.PCG_STAB;
  if (!D || !D.rank || !D.val || !D.mv || !D.nm) return;

  /* 下标顺序必须和游戏 bundle 的 49301+ve 一一对应 */
  var PLATES = [
    ['fire', '火'], ['water', '水'], ['grass', '草'], ['electric', '电'],
    ['ice', '冰'], ['fighting', '格斗'], ['poison', '毒'], ['ground', '地面'],
    ['flying', '飞行'], ['psychic', '超能'], ['bug', '虫'], ['rock', '岩石'],
    ['ghost', '幽灵'], ['dragon', '龙'], ['dark', '恶'], ['steel', '钢']
  ];

  var STAT = 2 * 120 + 5;      // Lv100 特攻（种族值 120）
  var PW = 100, ACC = 89.09;   // 制裁光砾：威力 100、曲线命中 89.09%、特殊
  var BASE = (D.bs && D.bs[493]) ? D.bs[493].slice() : [120, 120, 120, 120, 120, 120];
  var RARE = (D.rr && D.rr[493] != null) ? D.rr[493] : 3;

  /* 给 popup.js 决定榜单要显示到第几名（本批最大插入名次是 11） */
  D.arceus = { ids: [], byType: {}, maxRank: 0 };

  PLATES.forEach(function (p, i) {
    var plate = p[0], zh = p[1];
    var id = 49301 + i;
    var key = 'judgment-' + plate;

    D.mv[key] = [PW, ACC, 0, '制裁光砾'];
    D.nm[id] = '阿尔宙斯（' + zh + '）';
    if (D.ty) D.ty[id] = [plate];          // 战斗属性牌 / 可等阶等也要认得新形态
    if (D.bs) D.bs[id] = BASE.slice();
    if (D.rr) D.rr[id] = RARE;

    var list = D.rank[plate];
    if (!list) return;
    var val = D.val(key, STAT);
    var at = list.length;
    for (var j = 0; j < list.length; j++) {
      if (val > D.val(list[j][1], list[j][2])) { at = j; break; }
    }
    list.splice(at, 0, [id, key, STAT]);

    D.arceus.ids.push(id);
    D.arceus.byType[plate] = id;
    D.arceus.maxRank = Math.max(D.arceus.maxRank, at + 1);
  });
})(typeof window !== 'undefined' ? window : this);
